Explore water state changesIce, liquid, invisible vapor, and heat.wc-phase-map{--pm-ink:#17394b;--pm-muted:#486474;--pm-paper:#fff;--pm-soft:#f1f8fa;--pm-line:#b8ced7;--pm-accent:#086b78;--pm-selected:#e2f3f2;--pm-heat:#994215;margin:16px 0;border:1px solid var(--pm-line);border-radius:18px;background:var(--pm-paper);color:var(--pm-ink);container:wc-phase-map/inline-size;overflow-wrap:break-word}
.wc-phase-map *{box-sizing:border-box}.wc-phase-map summary{display:flex;align-items:center;gap:12px;min-height:64px;padding:16px;cursor:pointer;list-style:none;border-radius:17px}.wc-phase-map summary::-webkit-details-marker{display:none}.wc-phase-map summary>svg{width:32px;height:32px;flex:none;color:var(--pm-accent)}.wc-phase-map summary>span{display:grid;gap:4px;min-width:0}.wc-phase-map summary strong{font-size:16px;line-height:1.35}.wc-phase-map summary small{font-size:13px;line-height:1.5;color:var(--pm-muted)}.wc-phase-map summary::after{content:'+';display:grid;place-items:center;width:28px;height:28px;flex:none;margin-left:auto;border:1px solid var(--pm-line);border-radius:8px;color:var(--pm-accent);font-size:20px;font-weight:700}.wc-phase-map[open]>summary::after{content:'−'}.wc-phase-map summary:hover{background:var(--pm-soft)}
.wc-pm-body{padding:0 18px 18px}.wc-pm-body p{font-size:14px;line-height:1.6;margin:0 0 12px}.wc-pm-scope{color:var(--pm-muted)}.wc-pm-states{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}.wc-pm-state{display:grid;justify-items:center;align-content:start;gap:7px;padding:15px 10px;text-align:center;border:1px solid var(--pm-line);border-radius:14px;background:var(--pm-soft);min-width:0}.wc-pm-state strong{font-size:15px;line-height:1.4}.wc-pm-state small{font-size:13px;line-height:1.5;color:var(--pm-muted)}.wc-pm-glyph{width:58px;height:58px;color:var(--pm-accent);fill:currentColor;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.wc-pm-glyph [data-outline]{fill:none}.wc-pm-glyph[data-phase-glyph=solid]{fill:none}
.wc-pm-workspace{display:grid;grid-template-columns:minmax(220px,.85fr) minmax(0,1.5fr);gap:18px;align-items:start}.wc-pm-chooser{display:grid;gap:14px;min-width:0}.wc-pm-pair{margin:0;padding:0;border:0;min-width:0}.wc-pm-pair legend{padding:0 0 7px;font-size:13px;line-height:1.5;font-weight:700;color:var(--pm-muted)}.wc-pm-pair-buttons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.wc-phase-map button{font:inherit;font-size:14px;line-height:1.4;min-height:44px;border:1px solid var(--pm-line);border-radius:10px;background:var(--pm-paper);color:var(--pm-ink);padding:10px;cursor:pointer;white-space:normal;overflow-wrap:normal;word-break:normal;min-width:0}.wc-phase-map button:hover:not(:disabled){background:var(--pm-soft);border-color:var(--pm-accent)}.wc-phase-map button:disabled{cursor:default;background:var(--pm-soft);color:var(--pm-muted)}.wc-phase-map :is(button,summary):focus-visible{outline:3px solid var(--pm-accent);outline-offset:3px}.wc-phase-map [tabindex='-1']:focus{outline:3px solid var(--pm-accent);outline-offset:3px}.wc-phase-map button[aria-pressed=true]{border:2px solid var(--pm-accent);padding:9px;background:var(--pm-selected);color:var(--pm-ink)}.wc-pm-route{display:grid;gap:5px;text-align:left;align-content:start}.wc-pm-route strong{font-size:14px;line-height:1.4}.wc-pm-route small{font-size:13px;line-height:1.5;color:var(--pm-muted)}.wc-pm-route-mark{font-size:13px;font-weight:700;color:var(--pm-accent)}
.wc-pm-detail{padding:18px;border:1px solid var(--pm-line);border-radius:16px;background:var(--pm-soft);min-width:0}.wc-pm-detail-header{display:flex;align-items:start;justify-content:space-between;gap:12px;margin-bottom:14px}.wc-pm-detail h4{margin:3px 0 0;font-size:22px;line-height:1.25;letter-spacing:-.02em}.wc-pm-kicker{font-size:13px;font-weight:700;color:var(--pm-muted)}.wc-pm-reverse{flex:none;max-width:150px}.wc-pm-flow{display:grid;grid-template-columns:minmax(0,1fr) 30px minmax(0,1fr);align-items:center;gap:8px;margin:0 0 14px}.wc-pm-flow-node{display:grid;justify-items:center;gap:6px;text-align:center;min-width:0}.wc-pm-flow-node>small{font-size:13px;color:var(--pm-muted)}.wc-pm-flow-node>strong{font-size:15px;line-height:1.4}.wc-pm-flow-arrow{width:30px;height:30px;color:var(--pm-accent);fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.wc-pm-example{padding:12px;border-left:3px solid var(--pm-accent);border-radius:0 9px 9px 0;background:var(--pm-paper)}.wc-pm-direct{font-weight:700;color:var(--pm-accent)}
.wc-pm-question{border:0;margin:18px 0 10px;padding:0;min-width:0}.wc-pm-question legend{font-size:15px;line-height:1.5;font-weight:700;padding:0 0 10px}.wc-pm-answers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.wc-pm-answers button{display:grid;gap:4px;text-align:left}.wc-pm-answers button>small{font-size:13px;line-height:1.5;color:var(--pm-muted)}.wc-pm-check{width:100%;font-weight:700!important}.wc-pm-feedback{margin:16px 0 0;padding-top:16px;border-top:1px solid var(--pm-line)}.wc-pm-feedback h5{margin:0 0 10px;font-size:16px;line-height:1.4}.wc-pm-feedback p:last-child{margin-bottom:0}.wc-pm-feedback[data-phase-result=unchecked]{color:var(--pm-muted)}.wc-pm-heat{display:grid;grid-template-columns:minmax(0,1fr) 52px minmax(0,1fr);align-items:center;gap:8px;margin:12px 0;padding:12px;border:1px solid var(--pm-line);border-radius:12px;background:var(--pm-paper);color:var(--pm-heat)}.wc-pm-heat>span{display:grid;gap:4px;text-align:center}.wc-pm-heat strong{font-size:14px;line-height:1.4}.wc-pm-heat small{font-size:13px;line-height:1.5}.wc-pm-heat svg{width:52px;height:30px;fill:none;stroke:currentColor;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.wc-pm-note{margin:16px 0 0!important;padding-top:14px;border-top:1px solid var(--pm-line);color:var(--pm-muted);font-size:13px!important}
